// v0.28 Green Maniac voice-over (ElevenLabs "Gork – Terrifying & Dark Creature", generated by the user, processed:
// silence trimmed, loudness-normalised to ≈ −16 LUFS, mono 96 kbps → public/audio/vo/).
//
//  • One line at a time; slots with an interval repeat while the game keeps asking for them (request() every frame),
//    and reset when the requests stop (e.g. Mobius leaves the room).
//  • The voice comes from Green Maniac: panned + attenuated from his position relative to the head (simple, robust
//    StereoPanner + distance gain, with a floor so a far taunt stays intelligible); updated every frame while speaking.
//  • While he speaks the music + ambience buses are ducked (−6 dB) and the subtitle shows "[GREEN MANIAC] …"
//    in the game language (only English audio exists so far: a Chinese game shows the Chinese subtitle under it).
//  • settings.voiceVolume (0…1), settings.subtitles.
import * as THREE from 'three';
import { audio } from '../core/audio.js';
import { settings } from '../core/settings.js';
import { t, getLang } from '../core/i18n.js';

const BASE = (import.meta.env?.BASE_URL || '/') + 'audio/vo/';
/** Lines per slot. text: subtitle per language; file per language (missing → falls back to 'en'). */
export const VO_LINES = {
  A: [ // chase start: Green Maniac waits outside the window, Mobius is still in his room
    { id: 'A1', file: { en: 'gm_A1_en.mp3' }, text: { en: 'Still hiding in your little room, Mobius? Come out… and play.', zh: '還躲在小房間裡嗎，小莫？出來……陪我玩玩。' } },
    { id: 'A2', file: { en: 'gm_A2_en.mp3' }, text: { en: 'Tick-tock, hero. My jet is getting bored.', zh: '滴答滴答，英雄。我的飛行器等得不耐煩了。' } },
    { id: 'A3', file: { en: 'gm_A3_en.mp3' }, text: { en: 'Jump out of that window… if you dare!', zh: '有膽就從窗戶跳出來啊！' } },
  ],
  // v0.29 B: the moment Mobius jumps out of the window (one line, alternating B1 / B2 per chase attempt). Generated with
  // ElevenLabs (Gork, eleven_v3) via the API; gain trims them to the A lines' loudness (≈ −16.9 LUFS).
  B: [
    { id: 'B1', file: { en: 'gm_B1_en.mp3' }, gain: 0.87, text: { en: 'There you are! Try to keep up!', zh: '終於出來啦！跟得上再說！' } },
    { id: 'B2', file: { en: 'gm_B2_en.mp3' }, gain: 0.91, text: { en: 'Finally! Let’s see what those webs can do.', zh: '總算來了！讓我看看你的光網有多厲害。' } },
  ],
};
// v0.28b intro police radio: dispatcher voice (ElevenLabs "Connery – Primetime Anchor Voice", eleven_v4) + radio
// processing (300–3100 Hz band, overdrive, compression, hiss + crackle bed, squelch bursts) → police_radio_en.mp3.
// Subtitle / tag come from i18n (story.radio / story.radioTag); it plays from the radio on the nightstand.
// v0.47 Story chase combat (design 4.5; drafts in the voice of the lines above). Generated with ElevenLabs (Gork, eleven_v3)
// through the connector and processed like the others (silence trimmed, ≈ −16 LUFS, mono 96 kbps). A line without a `file`
// (rejected and removed) is subtitle-only: the text shows for `dur` seconds, nothing plays, nothing is ducked. Not yet auditioned.
VO_LINES.STALL = [ // his jet stalls (one line per stall, in turn)
  { id: 'STALL1', file: { en: 'gm_STALL1_en.mp3' }, dur: 1.6, text: { en: 'My jet!', zh: '我的飛行器！' } },
  { id: 'STALL2', file: { en: 'gm_STALL2_en.mp3' }, dur: 1.8, text: { en: 'No, no, no!', zh: '不、不、不！' } },
  { id: 'STALL3', file: { en: 'gm_STALL3_en.mp3' }, dur: 2.0, text: { en: 'You little pest!', zh: '你這隻煩人的小蟲！' } },
];
VO_LINES.PUNCHED = [ // after a punch
  { id: 'PUNCHED1', file: { en: 'gm_PUNCHED1_en.mp3' }, dur: 2.0, text: { en: 'You’ll pay for that!', zh: '這筆帳我記下了！' } },
  { id: 'PUNCHED2', file: { en: 'gm_PUNCHED2_en.mp3' }, dur: 2.0, text: { en: 'Lucky shot, bug!', zh: '算你走運，小蟲！' } },
];
VO_LINES.ESCAPE = [ // the final escape after the factory
  { id: 'ESCAPE1', file: { en: 'gm_ESCAPE1_en.mp3' }, dur: 4.0, text: { en: 'This city can’t hold me, Mobius. Until next time!', zh: '這座城市困不住我，小莫。下次再會！' } },
];
VO_LINES.RADIO = [{ id: 'RADIO', file: { en: 'police_radio_en.mp3' }, textKey: 'story.radio', tagKey: 'story.radioTag', gain: 1.0, yOff: 0.1 }];
export const VO_SLOTS = {
  // first line 1.2 s after he turns to the window, then every ~11 s; fadeOnStop: when the game stops asking for the
  // slot (Mobius jumps out of the window) the line being spoken fades out over 0.8 s instead of playing to its end
  A: { first: 1.2, interval: 11, order: 'sequence', fadeOnStop: 0.8 },
};
const GAP = 2.5; // s of silence between any two lines

const _v = new THREE.Vector3(), _c = new THREE.Vector3(), _q = new THREE.Quaternion();

export class VoiceDirector {
  constructor(app) {
    this.app = app;
    this.buffers = new Map();
    this.current = null; // { src, gain, pan, line, source, until }
    this.slots = {}; // slot → { since, next, idx, lastReq }
    this.time = 0; this.lastEnd = -1e9;
    this._loading = null;
    this.stats = { played: 0, failed: 0 };
  }
  _bus() {
    const A = audio; if (!A.ctx) return null;
    if (!A.voice) { A.voice = A.ctx.createGain(); A.voice.connect(A.master); }
    A.voice.gain.value = settings.voiceVolume ?? 1;
    return A.voice;
  }
  /** Preload every line file (small, ~0.1 MB each). Safe to call before the audio context exists (it waits). */
  preload() {
    if (this._loading || !audio.ctx) return this._loading;
    const urls = new Set(); for (const lines of Object.values(VO_LINES)) for (const l of lines) for (const f of Object.values(l.file || {})) urls.add(f);
    this._loading = Promise.all([...urls].map((f) => audio.loadBuffer(BASE + f).then((b) => this.buffers.set(f, b), (e) => { this.stats.failed++; console.warn('voice', f, e); })));
    return this._loading;
  }
  get speaking() { return !!this.current; }

  /**
   * Ask for a slot this frame. While requested every frame it plays its first line after VO_SLOTS[slot].first
   * seconds and then one every .interval seconds (never overlapping another line). Stops asking → state resets.
   * source: an Object3D the voice comes from (Green Maniac).
   */
  request(slot, source) {
    const S = VO_SLOTS[slot]; if (!S) return;
    let st = this.slots[slot];
    if (!st || this.time - st.lastReq > 0.6) st = this.slots[slot] = { since: this.time, next: this.time + S.first, idx: 0, lastReq: this.time };
    st.lastReq = this.time; st.source = source;
    if (this.current || this.time < st.next || this.time - this.lastEnd < GAP) return;
    const lines = VO_LINES[slot]; if (!lines?.length) return;
    const line = lines[st.idx % lines.length]; st.idx++;
    if (this.play(line, source, slot)) st.next = this.time + S.interval; else st.next = this.time + 1; // not loaded yet → retry soon
  }
  /** Play one line now (returns false if its audio is not ready). */
  play(line, source, slot = null) {
    const bus = this._bus(); if (!bus) return false;
    this.preload();
    const lang = String(getLang?.() || 'en').startsWith('zh') ? 'zh' : 'en';
    if (!line.file) return this._subtitleOnly(line, lang); // v0.47: a line with no recording yet
    const file = line.file[lang] || line.file.en, buf = this.buffers.get(file);
    if (!buf) return false;
    const c = audio.ctx, src = c.createBufferSource(); src.buffer = buf;
    const gain = c.createGain(), pan = c.createStereoPanner ? c.createStereoPanner() : null;
    gain.gain.value = 0;
    if (pan) src.connect(gain).connect(pan).connect(bus); else src.connect(gain).connect(bus);
    src.start();
    this.current = { src, gain, pan, line, source, slot, until: this.time + buf.duration, fading: false };
    src.onended = () => { if (this.current?.src === src) { this.current = null; this.lastEnd = this.time; this._duck(false); } };
    this._place(true);
    this._duck(true);
    const tag = line.tagKey ? t(line.tagKey) : lang === 'zh' ? `【${t('char.boss')}】` : `[${t('char.boss').toUpperCase()}]`;
    const text = line.textKey ? t(line.textKey) : line.text[lang] || line.text.en;
    if (settings.subtitles !== false) this.app.story?.say?.(tag, text, buf.duration + 0.6);
    this.stats.played++;
    return true;
  }
  /** v0.47: a line that has no recording: its subtitle for line.dur seconds (no sound, no ducking); it still occupies the "one line at a time" slot. */
  _subtitleOnly(line, lang) {
    const dur = line.dur ?? 2;
    this.current = { src: null, gain: null, pan: null, line, source: null, slot: null, until: this.time + dur, fading: false, silent: true };
    const tag = lang === 'zh' ? `【${t('char.boss')}】` : `[${t('char.boss').toUpperCase()}]`;
    if (settings.subtitles !== false) this.app.story?.say?.(tag, line.text[lang] || line.text.en, dur + 0.4);
    this.stats.played++; this.stats.silent = (this.stats.silent || 0) + 1;
    return true;
  }
  /** Fade the current line out over `sec` and stop it (subtitle cleared too). */
  fadeOut(sec = 0.8) {
    const C = this.current; if (!C || C.fading) return;
    C.fading = true;
    if (C.silent) { C.until = this.time; const st = this.app.story; if ([C.line.text.zh, C.line.text.en].includes(st?.subtitle?.text)) st.say('', '', 0); return; } // v0.47: a subtitle-only line just ends
    const t0 = audio.ctx.currentTime;
    C.gain.gain.cancelScheduledValues(t0); C.gain.gain.setValueAtTime(C.gain.gain.value, t0); C.gain.gain.linearRampToValueAtTime(0, t0 + sec);
    try { C.src.stop(t0 + sec + 0.05); } catch { /* */ }
    C.until = Math.min(C.until, this.time + sec);
    const st = this.app.story, txt = C.line.textKey ? [t(C.line.textKey)] : [C.line.text.zh, C.line.text.en]; if (txt.includes(st?.subtitle?.text)) st.say('', '', 0);
  }
  /**
   * One-shot line right now (the intro radio, the window jump). Lines of a slot rotate on every call.
   * interrupt: a line already playing is faded out quickly (0.25 s) instead of blocking this one.
   * Returns the duration (0 = not ready / blocked).
   */
  say(slot, source, { interrupt = false } = {}) {
    const lines = VO_LINES[slot]; if (!lines?.length) return 0;
    if (this.current) { if (!interrupt) return 0; this.fadeOut(0.25); this.current = null; }
    this._sayIdx ??= {};
    const i = this._sayIdx[slot] ?? 0, line = lines[i % lines.length];
    if (!this.play(line, source, null)) return 0;
    this._sayIdx[slot] = i + 1;
    return this.current.until - this.time;
  }
  stop() { if (this.current) { try { this.current.src?.stop(); } catch { /* */ } this.current = null; this.lastEnd = this.time; this._duck(false); } }
  _duck(on) {
    const A = audio; if (!A.ctx) return;
    const t0 = A.ctx.currentTime, k = on ? 0.5 : 1; // −6 dB
    for (const b of [A.music, A.ambient]) if (b) b.gain.setTargetAtTime((b === A.music ? settings.musicVolume : settings.musicVolume * 0.6) * k, t0, on ? 0.08 : 0.4);
  }
  /** Position: pan from the source's direction in head space, gain from distance (floor 0.5 so far lines stay clear). */
  _place(instant) {
    const C = this.current; if (!C || C.silent) return;
    const cam = this.app.camera;
    let panV = 0, g = 1;
    if (C.source) {
      C.source.getWorldPosition(_v); _v.y += C.line.yOff ?? 1.4; // Green Maniac: head height; the radio: itself
      cam.getWorldPosition(_c); cam.getWorldQuaternion(_q);
      const d = _v.distanceTo(_c);
      _v.sub(_c).applyQuaternion(_q.invert()); // head space: +x right, −z ahead
      panV = THREE.MathUtils.clamp(_v.x / Math.max(1, Math.hypot(_v.x, _v.z)), -1, 1) * 0.75;
      g = Math.max(0.5, Math.min(1, 12 / Math.max(12, d)) ** 0.5);
    }
    const t0 = audio.ctx.currentTime, tc = instant ? 0.01 : 0.08;
    C.gain.gain.setTargetAtTime(1.15 * g * (C.line.gain ?? 1), t0, tc);
    if (C.pan) C.pan.pan.setTargetAtTime(panV, t0, tc);
  }
  update(dt) {
    this.time += dt;
    if (!this.buffers.size && audio.ctx) this.preload();
    const C = this.current;
    if (C && !C.fading && C.slot) { const S = VO_SLOTS[C.slot], st = this.slots[C.slot]; if (S?.fadeOnStop && st && this.time - st.lastReq > 0.25) this.fadeOut(S.fadeOnStop); }
    if (this.current) { if (!this.current.fading) this._place(false); if (this.time > this.current.until + (this.current.silent ? 0 : 1)) { const silent = this.current.silent; this.current = null; this.lastEnd = this.time; if (!silent) this._duck(false); } }
    if (audio.voice) audio.voice.gain.value = settings.voiceVolume ?? 1;
  }
}
